using System;
using System.Collections;
using System.IO;
using UnityEngine;
namespace Veilbound {public partial class VeilGame {
 void GrantMaterialSlots(Settlement c,int source,int rank=3){c.researchRanks[LibraryResearch.Index(source==0?"leather-slots":"cloth-slots")]=rank;}
 void CheckMaterialProcessing(){
  QueueCheck(ProductionTime.NextUnit(.9999999999999999,1)>.9,"whole-unit boundaries remain positive near floating-point integer values");
  var c=QueueSample();c.AddResource(3,0,1);c.AddResource(4,0,1);c.AddResource(2,0,4);QueueCheck(!c.Craft(3,1,out _)&&c.ResourceAmount(2,0)==4&&c.ResourceAmount(5,0)==0,"raw fibres cannot directly craft cloth gear");c.QueueMaterialProcessing(1,0,4,out _);c.Tick(4/c.MaterialProcessingSpeed*60,1);QueueCheck(c.ResourceAmount(2,0)==0&&c.ResourceAmount(5,0)==4&&c.Craft(3,1,out _)&&c.ResourceAmount(5,0)==0,"fibres become finished cloth before equipment crafting");
  c=QueueSample();c.QueueSettlementJob(5,"",2,3,1,0,out _);c.Tick(100*60,1);QueueCheck(c.Owned(3,2)>0&&c.settlementQueue.Count==0&&c.ResourceAmount(1,0)<1e-7&&c.ResourceAmount(2,0)<1e-7&&c.ResourceAmount(4,0)<1e-7&&c.ResourceAmount(5,0)<1e-7,"automatic supply gathers hides/fibres, processes leather/cloth and crafts gear without surplus");
  c=QueueSample();GrantMaterialSlots(c,0);c.AddResource(1,0,5);c.QueueMaterialProcessing(0,0,5,out _);c.Tick(2/c.MaterialProcessingSpeed*60,1);QueueCheck(c.ResourceAmount(4,0)==5&&c.ProcessingOrders(0).Count==0&&c.ResourceAmount(1,0)==0,"four leather workers complete five units in two waves with no duplicates");
  c=QueueSample();c.researchRanks[LibraryResearch.Index("clothier")]=2;QueueCheck(!c.StartResearch("leather-slots",out _),"processing slot research requires Clothier tier three");c.researchRanks[LibraryResearch.Index("clothier")]=3;c.metalBars[1]=3;c.StartResearch("leather-slots",out _);c.Tick(LibraryResearch.Duration("leather-slots",1)*60,1);QueueCheck(c.MaterialProcessingSlotCount(0)==2&&c.MaterialProcessingSlotCount(1)==1,"leather and cloth side research unlock independently");
  c=QueueSample();c.AddResource(1,0,2);c.AssignMaterialProcessingSlot(0,0,0,out _);c.Tick(6,1);var loaded=JsonUtility.FromJson<Settlement>(JsonUtility.ToJson(c));c.Tick(300,1);loaded.Tick(300,1);QueueCheck(c.ResourceAmount(4,0)==2&&loaded.ResourceAmount(4,0)==2&&c.ResourceAmount(1,0)==0&&loaded.ResourceAmount(1,0)==0,"manual processing preserves paid raw inputs and partial work across saving");
  c=QueueSample();GrantMaterialSlots(c,1);c.AddResource(2,0,5);c.QueueMaterialProcessing(1,0,5,out _);c.Tick(6,1);c.CancelMaterialProcessing(1,c.ProcessingOrders(1)[0].id);c.Tick(600,1);QueueCheck(c.ResourceAmount(2,0)==5&&c.ResourceAmount(5,0)==0,"manual processing cancellation refunds unfinished raw inputs once");
  c=QueueSample();GrantMaterialSlots(c,1);c.AddResource(2,0,4);c.QueueSettlementJob(5,"",1,3,1,0,out _);c.Tick(6,1);c.RemoveSettlementJob(c.settlementQueue[0].id);c.Tick(600,1);QueueCheck(c.ResourceAmount(2,0)==4&&c.ResourceAmount(5,0)==0,"cancelled gear demand refunds all unfinished automatic cloth workers");
  c=QueueSample();GrantMaterialSlots(c,0,1);c.AddResource(1,1,3);c.AssignMaterialProcessingSlot(0,1,1,out _);c.QueueSettlementJob(5,"",2,3,1,0,out _);c.Tick(100*60,1);QueueCheck(c.ResourceAmount(4,1)==3&&c.Owned(3,2)>0&&c.ProcessingSlots(0)[1].assigned==1,"a manual cured-leather stockpile runs alongside automatic leather and cloth supply");
  c=QueueSample();c.QueueSettlementJob(5,"",2,3,1,0,out _);var stepped=JsonUtility.FromJson<Settlement>(JsonUtility.ToJson(c));c.Tick(100*60,1);for(int i=0;i<6000;i++)stepped.Tick(1,1);QueueCheck(c.Owned(3,2)>0&&stepped.Owned(3,2)>0,"bulk and frame ticks both finish the gather/process/craft chain");for(int f=1;f<6;f++)if(f!=3)for(int i=0;i<5;i++)QueueCheck(Math.Abs(c.ResourceAmount(f,i)-stepped.ResourceAmount(f,i))<1e-6,"processing stocks agree under bulk/frame timing "+f+"/"+i);
  c=QueueSample();c.AddResource(2,0,12);c.QueueSettlementJob(7,"",0,0,12,0,out _);c.Tick(20*60,1);QueueCheck(c.ResourceAmount(5,0)==12&&c.ResourceAmount(2,0)==0&&c.settlementQueue.Count==0,"explicit processing requests respect batch quantity without re-queuing the full batch");
  c=QueueSample();c.stone=0;c.AddResource(2,0,4);c.AddResource(1,0,4);c.QueueSettlementJob(0,"housing",0,0,1,0,out _);c.QueueSettlementJob(5,"",1,3,1,0,out _);c.Tick(60,1);QueueCheck(c.ResourceAmount(2,0)>=4-1e-7&&c.ResourceAmount(5,0)==0,"lower-priority processing cannot consume raw fibres reserved for an earlier construction");c.stone+=15;c.Tick(30*60,1);QueueCheck(c.housingTier==1&&c.Owned(3,1)>0,"processing resumes using newly gathered fibres after the first reservation is spent");
  c=QueueSample();c.QueueSettlementJob(5,"",2,3,1,0,out _);QueueCheck(c.FilterSettlementPriorities(4,0).Count==1&&c.FilterSettlementPriorities(5,0).Count==1&&c.FilterSettlementPriorities(1,0).Count==1&&c.FilterSettlementPriorities(2,0).Count==1,"resource filters follow finished leather/cloth back to their raw inputs");
  c=QueueSample();c.cloth=7.25;c.leather=9.5;var migrated=JsonUtility.FromJson<Settlement>(JsonUtility.ToJson(c));migrated.EnsureProcessedStocks();QueueCheck(migrated.cloth==7.25&&migrated.leather==9.5&&migrated.ResourceTotal(4)==0&&migrated.ResourceTotal(5)==0,"existing raw stocks remain raw with no silent conversion or stock loss");
  QueueCheck(!c.AssignMaterialProcessingSlot(0,3,0,out _)&&!c.AssignMaterialProcessingSlot(0,0,4,out _),"processing slot and material tier locks are enforced");
  Debug.Log("VEILBOUND_MATERIAL_PROCESSING_PASS");
 }
 IEnumerator MaterialProcessingScreenshots(string output){
  city=QueueSample();city.clothier=5;for(int source=0;source<2;source++){GrantMaterialSlots(city,source);for(int i=0;i<5;i++)city.AddResource(source==0?1:2,i,12);}city.AssignMaterialProcessingSlot(0,1,1,out _);city.AssignMaterialProcessingSlot(1,1,1,out _);city.QueueSettlementJob(5,"",2,2,1,0,out _);city.Tick(6,1);libraryResearchOpen=false;OpenMaterialProcessing(0);yield return CardScreenshot(Path.Combine(output,"11-leather-processing.png"));OpenMaterialProcessing(1);yield return CardScreenshot(Path.Combine(output,"12-cloth-processing.png"));
  OpenMaterialSlotResearch(1);yield return CardScreenshot(Path.Combine(output,"13-processing-research.png"));libraryResearchOpen=false;materialProcessingOpen=false;
 }
